// Input Validation Utilities
export const validationRules = {
  // Email validation (Gmail only)
  email: {
    required: true,
    pattern: /^[a-zA-Z0-9._%+-]+@gmail\.com$/,
    message: 'Please enter a valid Gmail address (username@gmail.com)'
  },

  // Phone number validation (10 digits)
  phone: {
    required: false,
    pattern: /^\d{10}$/,
    message: 'Please enter a valid 10-digit phone number'
  },

  // Password validation
  password: {
    required: true,
    minLength: 8,
    pattern: /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/,
    message: 'Password must be at least 8 characters with uppercase, lowercase, number, and special character'
  },

  // Username validation
  username: {
    required: true,
    minLength: 3,
    maxLength: 20,
    pattern: /^[a-zA-Z0-9_]+$/,
    message: 'Username must be 3-20 characters (letters, numbers, underscore only)'
  },

  // Full name validation
  fullName: {
    required: true,
    minLength: 2,
    maxLength: 50,
    pattern: /^[a-zA-Z\s]+$/,
    message: 'Full name must only contain letters and spaces'
  },

  // Movie title validation
  movieTitle: {
    required: true,
    minLength: 1,
    maxLength: 100,
    pattern: /^[a-zA-Z0-9\s:.,'-]+$/,
    message: 'Movie title contains invalid characters'
  },

  // Price validation
  price: {
    required: true,
    min: 0,
    max: 9999,
    message: 'Price must be between 0 and 9999'
  },

  // Date validation
  date: {
    required: true,
    pattern: /^\d{4}-\d{2}-\d{2}$/,
    message: 'Date must be in YYYY-MM-DD format'
  },

  // Time validation
  time: {
    required: true,
    pattern: /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/,
    message: 'Time must be in HH:MM format'
  }
};

// XSS Prevention
export const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;

  return input
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*<\/script>|<\/script>)/gi, '')
    .replace(/<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*<\/iframe>|<\/iframe>)/gi, '')
    .replace(/javascript:/gi, '')
    .replace(/on\w+\s*=/gi, '')
    .trim();
};

// SQL Injection Prevention
export const sanitizeSQL = (input) => {
  if (typeof input !== 'string') return input;

  return input
    .replace(/['"\\;]/g, '')
    .replace(/--/g, '')
    .replace(/\/\*/g, '')
    .replace(/\b(DROP|DELETE|INSERT|UPDATE|CREATE|ALTER|EXEC|UNION|SELECT)\b/gi, '')
    .trim();
};

// File validation
export const validateFile = (file) => {
  const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];
  const maxSize = 5 * 1024 * 1024; // 5MB

  if (!allowedTypes.includes(file.type)) {
    return { valid: false, message: 'Only JPEG, PNG, and WebP images are allowed' };
  }

  if (file.size > maxSize) {
    return { valid: false, message: 'File size must be less than 5MB' };
  }

  return { valid: true };
};

// Comprehensive validation function
export const validateField = (fieldName, value, customRules = {}) => {
  const rules = { ...validationRules[fieldName], ...customRules };

  if (rules.required && (!value || value.toString().trim() === '')) {
    return { valid: false, message: `${fieldName} is required` };
  }

  if (rules.minLength && value.toString().length < rules.minLength) {
    return { valid: false, message: `${fieldName} must be at least ${rules.minLength} characters` };
  }

  if (rules.maxLength && value.toString().length > rules.maxLength) {
    return { valid: false, message: `${fieldName} must be no more than ${rules.maxLength} characters` };
  }

  if (rules.min && parseFloat(value) < rules.min) {
    return { valid: false, message: `${fieldName} must be at least ${rules.min}` };
  }

  if (rules.max && parseFloat(value) > rules.max) {
    return { valid: false, message: `${fieldName} must be no more than ${rules.max}` };
  }

  if (rules.pattern && !rules.pattern.test(value.toString())) {
    return { valid: false, message: rules.message };
  }

  return { valid: true };
};
